package cn.mop.domain.backup;
import cn.mop.domain.DomainException;
import cn.mop.domain.backup.BackupRunState.*;
import org.junit.jupiter.api.Test;
import java.time.*;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class BackupRunSnapshotTest {
 static final UUID TENANT=UUID.fromString("74000000-0000-4000-8000-000000000001"),ASSET=UUID.fromString("74000000-0000-4000-8000-000000000002");
 static final Instant AT=Instant.parse("2026-10-21T00:00:00Z");
 static BackupRunState queued(){return BackupRunState.queued(TENANT,ASSET,AT);}
 static StoredVersion stored(Instant at){return new StoredVersion(TENANT,ASSET,UUID.fromString("74000000-0000-4000-8000-000000000003"),"a".repeat(64),100,at);}
 static Snapshot snapshot(long version,List<Attempt> rows){return new Snapshot(TENANT,ASSET,AT,version,rows);}
 @Test void everyValidStateRoundTripsWithoutGrantingAutomaticTicketing(){var q=queued();var r=q.start(0,AT);var unknown=r.markUnknown(1,AT.plusSeconds(1));var failed=unknown.fail(2,AT.plusSeconds(2),Failure.STORAGE_FAILED);var retry=failed.start(3,AT.plusSeconds(602));var success=retry.succeed(4,AT.plusSeconds(603),stored(AT.plusSeconds(603)));for(var state:List.of(q,r,unknown,failed,retry,success)){var result=BackupRunState.rehydrate(state.snapshot());assertEquals(state.snapshot(),result.snapshot());assertEquals(state.state(),result.state());assertEquals(state.nextAttemptAt(),result.nextAttemptAt());assertEquals(state.reconciliationRequired(),result.reconciliationRequired());assertFalse(result.automaticTicketAllowed());assertNull(result.failureCountSemantics());}}
 @Test void snapshotListIsDetachedAndImmutable(){var rows=new ArrayList<Attempt>();var snapshot=snapshot(0,rows);rows.add(queued().start(0,AT).attempts().get(0));assertTrue(snapshot.attempts().isEmpty());assertThrows(UnsupportedOperationException.class,()->snapshot.attempts().add(rows.get(0)));}
 @Test void nullIdentityTimeAndInvalidVersionsReject(){assertThrows(DomainException.class,()->BackupRunState.rehydrate(null));for(var s:List.of(new Snapshot(null,ASSET,AT,0,List.of()),new Snapshot(TENANT,null,AT,0,List.of()),new Snapshot(TENANT,ASSET,null,0,List.of()),snapshot(-1,List.of()),snapshot(9007199254740992L,List.of()),snapshot(1,List.of())))assertThrows(DomainException.class,()->BackupRunState.rehydrate(s));}
 @Test void nullAndOversizedAttemptCollectionsReject(){assertThrows(DomainException.class,()->snapshot(0,null));assertThrows(DomainException.class,()->snapshot(1,Arrays.asList((Attempt)null)));var a=queued().start(0,AT).attempts().get(0);assertThrows(DomainException.class,()->snapshot(8,List.of(a,a,a,a)));}
 @Test void attemptNumberAndQueueChronologyMustMatch(){var a=new Attempt(2,AT,AT,null,Outcome.RUNNING,null,null);assertThrows(DomainException.class,()->BackupRunState.rehydrate(snapshot(1,List.of(a))));var early=new Attempt(1,AT.minusSeconds(1),AT.minusSeconds(1),null,Outcome.RUNNING,null,null);assertThrows(DomainException.class,()->BackupRunState.rehydrate(snapshot(1,List.of(early))));}
 @Test void runningStateCannotInventHeartbeatOrPriorFirstAttemptTransitions(){var advanced=new Attempt(1,AT,AT.plusSeconds(1),null,Outcome.RUNNING,null,null);assertThrows(DomainException.class,()->BackupRunState.rehydrate(snapshot(2,List.of(advanced))));var running=queued().start(0,AT).attempts();assertThrows(DomainException.class,()->BackupRunState.rehydrate(snapshot(2,running)));}
 @Test void onlyFailedPriorAttemptCanBeFollowedByRetry(){var next=new Attempt(2,AT.plusSeconds(600),AT.plusSeconds(600),null,Outcome.RUNNING,null,null);var r=queued().start(0,AT);for(var prior:List.of(r.attempts().get(0),r.markUnknown(1,AT).attempts().get(0),r.succeed(1,AT,stored(AT)).attempts().get(0)))assertThrows(DomainException.class,()->BackupRunState.rehydrate(snapshot(4,List.of(prior,next))));}
 @Test void retryCannotSkipTenMinuteDelay(){var first=queued().start(0,AT).fail(1,AT,Failure.READ_TIMEOUT).attempts().get(0);var early=new Attempt(2,AT.plusSeconds(599),AT.plusSeconds(599),null,Outcome.RUNNING,null,null);assertThrows(DomainException.class,()->BackupRunState.rehydrate(snapshot(3,List.of(first,early))));var exact=new Attempt(2,AT.plusSeconds(600),AT.plusSeconds(600),null,Outcome.RUNNING,null,null);assertEquals(State.RUNNING,BackupRunState.rehydrate(snapshot(3,List.of(first,exact))).state());}
 @Test void transitionLowerBoundRejectsImpossibleVersionsButRetainsUnknownObservations(){var unknown=queued().start(0,AT).markUnknown(1,AT);assertThrows(DomainException.class,()->BackupRunState.rehydrate(snapshot(1,unknown.attempts())));assertEquals(99,BackupRunState.rehydrate(snapshot(99,unknown.attempts())).version());var failed=queued().start(0,AT).fail(1,AT,Failure.READ_TIMEOUT);assertThrows(DomainException.class,()->BackupRunState.rehydrate(snapshot(1,failed.attempts())));}
 @Test void storedVersionMustBeScopedToRun(){var foreign=new StoredVersion(UUID.randomUUID(),ASSET,UUID.randomUUID(),"a".repeat(64),100,AT);var a=new Attempt(1,AT,AT,AT,Outcome.SUCCEEDED,null,foreign);assertThrows(DomainException.class,()->BackupRunState.rehydrate(snapshot(2,List.of(a))));}
 @Test void retryWaitCannotOverflowSupportedTimestampRange(){Instant end=Instant.parse("9999-12-31T23:59:59.999Z");var a=new Attempt(1,end,end,end,Outcome.FAILED,Failure.STORAGE_FAILED,null);assertThrows(DomainException.class,()->BackupRunState.rehydrate(new Snapshot(TENANT,ASSET,end,2,List.of(a))));}
 @Test void unknownAndTerminalSnapshotsKeepTheirTransitionRestrictions(){var r=queued().start(0,AT);var unknown=BackupRunState.rehydrate(r.markUnknown(1,AT).snapshot());assertThrows(DomainException.class,()->unknown.start(unknown.version(),AT.plusSeconds(10000)));var terminal=BackupRunState.rehydrate(r.succeed(1,AT,stored(AT)).snapshot());assertThrows(DomainException.class,()->terminal.fail(terminal.version(),AT.plusSeconds(1),Failure.READ_TIMEOUT));}
}
